function reportSegs(r){return A(r?.transcript?.segments).map(x=>({start:Number(x.start)||0,end:finite(x.end)?Number(x.end):null,text:clean(x.text)})).filter(x=>x.text).sort((a,b)=>a.start-b.start)}
