function sentenceRows(r){const out=[];for(const s of reportSegs(r)){const ps=s.text.split(/(?<=[.!?])\s+|\s+>>\s+/).map(clean).filter(Boolean),len=Math.max(1,(s.end??s.start+Math.max(4,words(s.text).length/2.4))-s.start),wc=ps.map(x=>Math.max(1,words(x).length)),tot=wc.reduce((a,b)=>a+b,0)||1;let p=0;for(let i=0;i<ps.length;i++){const start=s.start+len*p/tot;p+=wc[i];if(words(ps[i]).length>=4)out.push({start,text:ps[i]})}}return out}
function deDupTokens(r){const out=[];for(const s of reportSegs(r)){let t=words(s.text);if(!t.length)continue;for(let len=Math.min(32,Math.floor(t.length/2));len>=3;len--){let ok=true;for(let i=0;i<len;i++)if(String(t[i]).toLowerCase()!==String(t[i+len]).toLowerCase()){ok=false;break}if(ok){t=[...t.slice(0,len),...t.slice(len*2)];break}}let ov=0;for(let n=Math.min(50,out.length,t.length);n>=2;n--){let ok=true;for(let i=0;i<n;i++)if(String(out[out.length-n+i]).toLowerCase()!==String(t[i]).toLowerCase()){ok=false;break}if(ok){ov=n;break}}out.push(...t.slice(ov))}return out}
function pacing(r){const dur=Number(r?.video?.duration||0),total=deDupTokens(r).length,wpm=dur>20?total/(dur/60):null;return{words:total,wpm:finite(wpm)&&wpm>=45&&wpm<=330?Math.round(wpm*10)/10:null}}
function minuteWpm(r){const dur=Number(r?.video?.duration||0),segs=reportSegs(r),out=[];for(let a=0;a<dur;a+=60){const b=Math.min(dur,a+60),tx=clean(segs.filter(s=>s.start<b&&(s.end??s.start+5)>=a).map(s=>s.text).join(' ')),n=words(tx).length;out.push({minute:Math.floor(a/60)+1,wpm:Math.round(n/((b-a)/60))})}return out}
