function keywords(s,n=10){const m=new Map;for(const w of toks(s))m.set(w,(m.get(w)||0)+1);return [...m.entries()].sort((a,b)=>b[1]-a[1]||b[0].length-a[0].length).slice(0,n).map(x=>x[0])}
function titleCoverage(r){const t=keywords(r?.video?.title||'',12);if(!t.length)return{first60:null,full:null};const f=new Set(toks(textAt(r,0,60))),a=new Set(toks(transcriptText(r)));return{first60:Math.round(t.filter(x=>f.has(x)).length/t.length*100),full:Math.round(t.filter(x=>a.has(x)).length/t.length*100)}}
