/* ---------- visible task telemetry; never hidden chain-of-thought ---------- */
const TASKS=[['evidence','Evidence agent','Strip + channel context'],['transcript','Transcript agent','Summary + takeaways + hooks'],['replay','Replay agent','Peaks + troughs + receipts'],['visual','Visual agent','Frames + motion + audio'],['package','Packaging agent','Title + thumbnail + promise'],['remake','Remake agent','Your brand-specific version'],['vault','Vault librarian','Bank hooks + packages + report'],['review','Cross-check agent','Verify + export']];
