/* ---------- profile / brand ---------- */
async function loadProfile(){const fallback=read(LS_PROFILE,{channel_name:'',channel_url:'',niche:'',subniche:'',target_audience:'',brand_rules:''});const c=sbClient(),id=uid();if(!c||!id)return fallback;try{const {data,error}=await c.from('ytintel_profiles').select('channel_name,channel_url,niche,subniche,target_audience,brand_rules,goal').eq('user_id',id).maybeSingle();if(error)throw error;return{...fallback,...(data||{})}}catch{return fallback}}
