/* ---------- public video media ---------- */
async function timeoutFetch(url,ms=11000){const c=new AbortController(),t=setTimeout(()=>c.abort(),ms);try{return await fetch(url,{signal:c.signal,headers:{accept:'application/json'}})}finally{clearTimeout(t)}}
async function ivVideo(id){let last='';for(const base of IV){try{const q=await timeoutFetch(`${base}/api/v1/videos/${encodeURIComponent(id)}?local=true`,12000);if(!q.ok){last=`${q.status}`;continue}const d=await q.json();if(d?.videoId||A(d?.storyboards).length)return{base,data:d}}catch(e){last=String(e?.message||e)}}throw Error(last||'No public storyboard source answered.')}
function pickStoryboard(xs){return A(xs).filter(x=>N(x.interval)>0&&x.templateUrl&&N(x.width)>0&&N(x.height)>0&&N(x.storyboardWidth)>0&&N(x.storyboardHeight)>0).sort((a,b)=>N(b.width)*N(b.height)-N(a.width)*N(a.height))[0]||null}
function absUrl(u,base){if(!u)return'';return /^https?:\/\//i.test(u)?u:base+u}
function frameAt(sb,seconds,base){if(!sb)return null;const interval=Math.max(1,N(sb.interval)||10000),count=Math.max(1,N(sb.count)||1),cols=Math.max(1,N(sb.storyboardWidth)||1),rows=Math.max(1,N(sb.storyboardHeight)||1),idx=Math.min(count-1,Math.max(0,Math.floor(Math.max(0,N(seconds)||0)*1000/interval))),per=cols*rows,sheet=Math.floor(idx/per),cell=idx%per,col=cell%cols,row=Math.floor(cell/cols),url=absUrl(String(sb.templateUrl||'').replace(/\$M/g,String(sheet)),base),px=cols<=1?0:col/(cols-1)*100,py=rows<=1?0:row/(rows-1)*100;return{seconds:idx*interval/1000,url,col,row,cols,rows,width:N(sb.width),height:N(sb.height),style:`background-image:url('${url.replace(/'/g,"%27")}');background-size:${cols*100}% ${rows*100}%;background-position:${px}% ${py}%`}}
function bestThumb(iv,r){const xs=A(iv?.data?.videoThumbnails).filter(x=>x.url).sort((a,b)=>(N(b.width)*N(b.height))-(N(a.width)*N(a.height)));return xs[0]?.url||`https://i.ytimg.com/vi/${encodeURIComponent(r?.video?.id||'')}/maxresdefault.jpg`}
async function loadImage(url,ms=10000){return await new Promise((resolve,reject)=>{const im=new Image();let done=false;const t=setTimeout(()=>{if(!done){done=true;reject(Error('image timeout'))}},ms);im.crossOrigin='anonymous';im.onload=()=>{if(done)return;done=true;clearTimeout(t);resolve(im)};im.onerror=()=>{if(done)return;done=true;clearTimeout(t);reject(Error('image CORS unavailable'))};im.src=url})}
function luma(r,g,b){return .2126*r+.7152*g+.0722*b}
function pixelVector(ctx,x,y,w,h,sw=24,sh=14){const c=document.createElement('canvas');c.width=sw;c.height=sh;const q=c.getContext('2d',{willReadFrequently:true});q.drawImage(ctx.canvas,x,y,w,h,0,0,sw,sh);const d=q.getImageData(0,0,sw,sh).data,ls=[],sats=[];let edges=0,bright=0;for(let i=0;i<d.length;i+=4){const R=d[i],G=d[i+1],B=d[i+2],mx=Math.max(R,G,B),mn=Math.min(R,G,B),L=luma(R,G,B);ls.push(L);sats.push(mx?((mx-mn)/mx)*100:0);bright+=L}for(let yy=0;yy<sh;yy++)for(let xx=0;xx<sw;xx++){const i=yy*sw+xx,v=ls[i],vr=xx<sw-1?ls[i+1]:v,vd=yy<sh-1?ls[i+sw]:v;if(Math.abs(v-vr)+Math.abs(v-vd)>70)edges++}const mean=bright/ls.length,variance=ls.reduce((a,v)=>a+(v-mean)*(v-mean),0)/ls.length;return{vec:ls,brightness:mean,contrast:Math.sqrt(variance),saturation:sats.reduce((a,b)=>a+b,0)/sats.length,edge_density:edges/(sw*sh)}}
function vecDiff(a,b){if(!a?.length||!b?.length)return null;let n=0;const L=Math.min(a.length,b.length);for(let i=0;i<L;i++)n+=Math.abs(a[i]-b[i]);return n/L}
async function spriteAnalysis(iv,r){const sb=pickStoryboard(iv?.data?.storyboards),dur=N(r?.video?.duration)||0;if(!sb)return{sb:null,frames:[],cuts_per_minute:null,motion:[],rhythm:[],error:'Public storyboard unavailable.'};const count=Math.min(90,Math.max(18,Math.ceil(dur/6))),times=Array.from({length:count},(_,i)=>dur*(i+.5)/count),sheets=new Map,frames=[];try{for(const t of times){const f=frameAt(sb,t,iv.base);if(!f)continue;if(!sheets.has(f.url)){const im=await loadImage(f.url);const can=document.createElement('canvas');can.width=im.naturalWidth||im.width;can.height=im.naturalHeight||im.height;const ctx=can.getContext('2d',{willReadFrequently:true});ctx.drawImage(im,0,0);sheets.set(f.url,ctx)}const ctx=sheets.get(f.url),cellW=ctx.canvas.width/f.cols,cellH=ctx.canvas.height/f.rows,px=pixelVector(ctx,f.col*cellW,f.row*cellH,cellW,cellH);frames.push({...f,...px})}if(frames.length<5)throw Error('Not enough readable storyboard cells');const diffs=[];for(let i=1;i<frames.length;i++)diffs.push({i,time:frames[i].seconds,diff:vecDiff(frames[i-1].vec,frames[i].vec),edge_jump:Math.abs(frames[i].edge_density-frames[i-1].edge_density)});const ds=diffs.map(x=>x.diff).filter(finite),med=median(ds)||0,mad=median(ds.map(x=>Math.abs(x-med)))||0,hard=Math.max(22,med+1.8*mad),soft=Math.max(13,med+1.0*mad),motion=diffs.filter(x=>x.diff>=soft).map(x=>({...x,type:x.diff>=hard?'cut / scene-change candidate':x.edge_jump>.07?'overlay / text / pop-up candidate':'zoom / reframing / transition candidate'})).slice(0,80),cuts=diffs.filter(x=>x.diff>=hard).length,windows=[];for(let a=0;a<dur;a+=30){const z=diffs.filter(x=>x.time>=a&&x.time<a+30);windows.push({start:a,count:z.filter(x=>x.diff>=soft).length,score:z.length?z.reduce((s,x)=>s+x.diff,0)/z.length:0})}return{sb,frames,cuts_per_minute:dur?Math.round(cuts/(dur/60)*10)/10:null,motion,rhythm:windows,thresholds:{soft,hard},error:null}}catch(e){return{sb,frames:[],cuts_per_minute:null,motion:[],rhythm:[],error:String(e?.message||e)}}}
async function thumbnailPixels(url){try{const im=await loadImage(url),c=document.createElement('canvas');c.width=320;c.height=Math.max(180,Math.round(320*(im.naturalHeight||im.height)/(im.naturalWidth||im.width)));const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(im,0,0,c.width,c.height);const p=pixelVector(ctx,0,0,c.width,c.height,48,27),cells=[];for(let y=0;y<3;y++)for(let x=0;x<3;x++)cells.push({x,y,...pixelVector(ctx,x*c.width/3,y*c.height/3,c.width/3,c.height/3,12,8)});const focus=[...cells].sort((a,b)=>(b.contrast+b.edge_density*80)-(a.contrast+a.edge_density*80))[0],pos=['top-left','top-centre','top-right','middle-left','centre','middle-right','bottom-left','bottom-centre','bottom-right'][focus.y*3+focus.x];return{brightness:Math.round(p.brightness),contrast:Math.round(p.contrast),saturation:Math.round(p.saturation),edge_density:Math.round(p.edge_density*100),focal_candidate:pos,error:null}}catch(e){return{error:String(e?.message||e)}}}
function vttSeconds(s){const p=String(s||'').replace(',','.').split(':').map(Number);if(p.some(Number.isNaN))return null;return p.length===3?p[0]*3600+p[1]*60+p[2]:p.length===2?p[0]*60+p[1]:p[0]}
function parseAudioEvents(vtt){const out=[];for(const b of String(vtt||'').split(/\r?\n\r?\n+/)){const m=b.match(/(\d{1,2}:\d{2}(?::\d{2})?[.,]\d+)\s+-->\s+(\d{1,2}:\d{2}(?::\d{2})?[.,]\d+)/);if(!m)continue;const st=vttSeconds(m[1]);if(st==null)continue;const text=b.split(/\r?\n/).slice(1).join(' ').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/\s+/g,' ').trim(),cues=[...text.matchAll(/\[([^\]]{2,70})\]/g)].map(x=>x[1].trim());if(/[♪♫]/.test(text))cues.push('music / sung audio');for(const cue of cues){if(!/(music|song|applause|laugh|cheer|sigh|gasp|door|click|ring|buzz|beep|whoosh|boom|bang|gunshot|engine|horn|typing|knock|alarm|footstep|clap|crowd|sound|sfx|transition)/i.test(cue))continue;out.push({start:st,type:/music|song|sung/i.test(cue)?'music':'sfx',label:cue})}}return out}
async function audioEvents(iv){const caps=A(iv?.data?.captions),cap=caps.find(x=>/^en(?:-|$)/i.test(x.languageCode||''))||caps.find(x=>/english/i.test(x.label||''))||caps[0];if(!cap?.url)return[];try{const q=await timeoutFetch(absUrl(cap.url,iv.base),10000);if(!q.ok)return[];return parseAudioEvents(await q.text())}catch{return[]}}

/* ---------- semantic evidence helpers ---------- */
function roleFor(line){const s=line.toLowerCase();if(/\b(i'?m going to|we'?re going to|you'?ll learn|i will show|i'?ll show|prove it|in this video|today i)\b/.test(s))return'promise';if(/\b\$[\d,]+|\b\d+(?:\.\d+)?%|dashboard|revenue|views?|subscribers?|proof|receipt|data\b/.test(s))return'proof / receipt';if(/\b(no,? this doesn'?t mean|what this means|in other words|not .* but)\b/.test(s))return'correction / re-hook';if(/\b(secret|nobody|you won'?t|what if|why|how|here'?s the catch)\b/.test(s))return'curiosity';if(/\b(biggest|massive|changes everything|important|ridiculous|huge|million|billion)\b/.test(s))return'stakes';if(/\b(next|another|now let'?s|moving on|finally|but first)\b/.test(s))return'transition';if(/\b(subscribe|link below|work with me|book a call|discord|buy|join)\b/.test(s))return'CTA';return'context / explanation'}
function firstPromise(r){return sentenceRows(r).filter(x=>x.start<60).find(x=>roleFor(x.text)==='promise')||null}
function payoffCandidates(r){const rx=/\b(result|proof|here'?s what happened|dashboard|made \$|earned \$|revenue|found|discovered|turns out|answer|payoff|we got|this worked|this means|easter egg|reveal)\b/i,out=[];for(const x of sentenceRows(r))if(x.start>5&&rx.test(x.text)&&out.every(y=>Math.abs(y.start-x.start)>18))out.push(x);return out.slice(0,16)}
