function parseTimestamp(t){const p=String(t||'').replace('≈','').split(':').map(Number);if(p.some(Number.isNaN))return 0;return p.length===3?p[0]*3600+p[1]*60+p[2]:p.length===2?p[0]*60+p[1]:p[0]||0}
